#define STEPS 44
float tubeRadius(float z, float a, float t){
    float ring = 0.5 + 0.5 * sin(z * 1.15 - t * 2.0);
    float rib  = 0.5 + 0.5 * sin(a * 5.0 + t * 0.7);
    return 1.05 + 0.13 * ring * rib + u_audio_bass * 0.10;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2  res = u_resolution;
    vec2  uv  = (fragCoord * 2.0 - res) / min(res.x, res.y);
    float t   = u_time * u_speed;

    vec3 ro = vec3(0.0, 0.0, t * 3.0);
    vec3 rd = normalize(vec3(uv, 1.55));
    ro.xy += (u_mouse - 0.5) * 0.30;

    vec3  col = vec3(0.0);
    float glow = 0.0, hit = 0.0, sHit = 0.0, s = 0.08;

    for (int i = 0; i < STEPS; i++){
        vec3  p = ro + rd * s;
        float r = length(p.xy);
        float a = atan(p.y, p.x);
        float R = tubeRadius(p.z, a, t);
        float d = R - r;                    // > 0 while inside the tube

        if (d < 0.70){                      // skip trig when far from the wall
            float ring = 0.5 + 0.5 * sin(p.z * 2.6 - t * 4.0);
            ring = ring * ring * ring;
            float rs  = 0.5 + 0.5 * sin(a * 9.0 - t * 0.6);
            float rib = rs * rs; rib = rib * rib; rib = rib * rib;
            float sp  = 0.5 + 0.5 * dot(p.xy / max(r, 1e-4),
                                 vec2(cos(t * 0.40), sin(t * 0.40)));
            float spoke = sp * sp; spoke = spoke * spoke;
            float e = ring * 1.20 + rib * 0.45 + spoke * 0.25;

            vec3  emit = mix(u_color1, u_color2, ring)
                       + u_accent * (rib * 0.8 + spoke * 0.4);
            float w = exp(-d * 5.0) * exp(-s * 0.13);
            col  += emit * e * w * 0.038 * u_intensity;
            glow += e * w;
        }
        if (d < 0.015){ hit = 1.0; sHit = s; break; }
        s += max(0.035, d * 0.80);
        if (s > 55.0) break;
    }
    col += u_accent * 0.10 * exp(-length(uv) * 4.5) * (1.0 + 0.6 * u_audio_treble);
    col += vec3(0.010, 0.012, 0.030) * (0.30 + 0.25 * glow);
    col += u_accent * hit * 0.10 * exp(-sHit * 0.35);
    col += u_color1 * 0.05 * glow * glow * 0.35;
    col  = pow(max(col, 0.0), vec3(0.92));
    fragColor = vec4(col, 1.0);
}

